FORM-008 inline error   : {"visible":true,"text":"Write something first. An empty note has nothing to hand off.","role":"alert","ariaInvalid":"true","focused":"box","describedby":"box-why box-err","describedbyResolves":true,"errIsNextToBox":"box-err"}
